MERGE `{{params.project_name}}.semantics_central.Customers` final
USING (
{{range_query}}
) staging
ON final.customer_id = staging.customer_id
WHEN MATCHED THEN
UPDATE SET
final.locale = staging.locale,
final.salutation = staging.salutation,
final.first_name = staging.first_name,
final.last_name = staging.last_name,
final.email = staging.email,
final.phone = staging.phone,
final.phone2 = staging.phone2,
final.sms_marketing = staging.sms_marketing,
final.email_marketing = staging.email_marketing,
final.created_by_crm = staging.created_by_crm,
final.customer_created_at = staging.customer_created_at,
final.customer_created_by_id = staging.customer_created_by_id,
final.customer_created_by = staging.customer_created_by,
final.customer_last_modified = staging.customer_last_modified,
final.customer_last_modified_by_id = staging.customer_last_modified_by_id,
final.customer_last_modified_by = staging.customer_last_modified_by,
final.deleted_at = staging.deleted_at,
final.deleted_by_id = staging.deleted_by_id,
final.deleted_by = staging.deleted_by,
final.country_id = staging.country_id,
final.data_privacy_consent_at = staging.data_privacy_consent_at,
final.digital_communication_consent_at = staging.digital_communication_consent_at,
final.city = staging.city,
final.postcode = staging.postcode,
final.customer_address = staging.customer_address
WHEN NOT MATCHED THEN
INSERT (
customer_id,
locale,
salutation,
first_name,
last_name,
email,
phone,
phone2,
sms_marketing,
email_marketing,
created_by_crm,
customer_created_at,
customer_created_by_id,
customer_created_by,
customer_last_modified,
customer_last_modified_by_id,
customer_last_modified_by,
deleted_at,
deleted_by_id,
deleted_by,
country_id,
data_privacy_consent_at,
digital_communication_consent_at,
city,
postcode,
customer_address
) VALUES (
staging.customer_id,
staging.locale,
staging.salutation,
staging.first_name,
staging.last_name,
staging.email,
staging.phone,
staging.phone2,
staging.sms_marketing,
staging.email_marketing,
staging.created_by_crm,
staging.customer_created_at,
staging.customer_created_by_id,
staging.customer_created_by,
staging.customer_last_modified,
staging.customer_last_modified_by_id,
staging.customer_last_modified_by,
staging.deleted_at,
staging.deleted_by_id,
staging.deleted_by,
staging.country_id,
staging.data_privacy_consent_at,
staging.digital_communication_consent_at,
staging.city,
staging.postcode,
staging.customer_address
)